        "DATASET_ID" as dataset_id,
        "BEST" as best,
        "DEM_TYPE" as dem_type,
        "SOURCE" as source,
        "VERTICALDATUM" as verticaldatum,
        "ACQUISITIONDATE" as acquisitiondate,
        "URL" as url,
        "METADATA" as metadata,
        "PUBDATE" as pubdate,
        "TITLE" as title,
        "RESOLUTION_X" as resolution_x,
        "RESOLUTION_Y" as resolution_y,
        "CDATE" as cdate,
